n class="remove-button" type="submit">Remove</button></form></div><p class="cart-save-status" data-cart-status role="status" hidden></p></div><span class="item-total"><?= e(format_money($item['line_total'])) ?></span></article><?php endforeach; ?><p class="page-footer-link"><a class="text-link" href="<?= e(url('/shop.php')) ?>">← Keep browsing</a></p></section><aside class="summary-box"><h2>Your lovely total</h2><div class="summary-row"><span>Flowers</span><span><?= e(format_money($summary['subtotal'])) ?></span></div><div class="summary-row"><span>Delivery or pickup</span><span>At checkout</span></div><div class="summary-row summary-total"><span>Subtotal</span><strong><?= e(format_money($summary['subtotal'])) ?></strong></div><?php if ($unavailable): ?><p class="field-error">Please update unavailable items to continue.</p><?php else: ?><a class="button" href="<?= e(url('/checkout.php')) ?>">Go to checkout ↗</a><?php endif; ?><p class="field-help">School demo · No real payment is collected.</p></aside></div><?php endif; ?></div><?php require dirname(__DIR__) . '/templates/footer.php'; ?>
